B.PT=new A.a5(57470,"MaterialIcons",null,!1)
B.Pg=new A.b4("infinite_scroll","The Bottomless Well","By automatically loading new content as you scroll, the app removes natural resting points that would otherwise prompt you to stop.","Aza Raskin / Infinite Scroll (2006)","Set a physical timer or use apps that impose hard limits on scrolling sessions.",B.lp,B.PT,"","Research shows users spend twice as much time on platforms with infinite scroll compared to traditional pagination.",!1)
